using EduCenterManagement.Services;using EduCenterManagement.Services.Common;using EduCenterManagement.ViewModels.TeacherComment;using Microsoft.AspNetCore.Mvc;
namespace EduCenterManagement.Controllers;
// TEMP: no authentication yet. Replace QueryStringCurrentUserContext with claims-based implementation and add [Authorize] when auth is merged.
[Route("TeacherComment")]
public sealed class TeacherCommentController(ICurrentUserContext current,ITeacherCommentService service):Controller { IActionResult NoUser(){return View("~/Views/ParentChildren/NoUser.cshtml");} [HttpGet("")]public async Task<IActionResult> Index(CancellationToken ct){if(current.UserId is null)return NoUser();var m=await service.GetClassesAsync(ct);if(m is null){ViewData["ProfileMessage"]="This user does not have a Teacher profile.";return NoUser();}return View(m);}[HttpGet("Students")]public async Task<IActionResult> Students(int classId,CancellationToken ct){var m=await service.GetStudentsAsync(classId,ct);return m is null?NotFound():View(m);}[HttpGet("Create")]public async Task<IActionResult> Create(int classId,int studentId,CancellationToken ct){var m=await service.GetFormAsync(classId,studentId,null,ct);return m is null?NotFound():View(m);}[HttpPost("Create")][ValidateAntiForgeryToken]public async Task<IActionResult> Create(TeacherCommentFormViewModel model,CancellationToken ct){if(!ModelState.IsValid){model.Sessions=(await service.GetFormAsync(model.ClassId,model.StudentId,null,ct))?.Sessions??Array.Empty<TeacherSessionOptionViewModel>();return View(model);}var id=await service.CreateAsync(model,ct);if(id is null)return NotFound();TempData["Success"]="Comment created.";return RedirectToAction(nameof(History),new{model.ClassId,model.StudentId});}[HttpGet("Edit")]public async Task<IActionResult> Edit(int id,int classId,int studentId,CancellationToken ct){var m=await service.GetFormAsync(classId,studentId,id,ct);return m is null?NotFound():View(m);}[HttpPost("Edit")][ValidateAntiForgeryToken]public async Task<IActionResult> Edit(TeacherCommentFormViewModel model,CancellationToken ct){if(!ModelState.IsValid)return View(model);if(!await service.UpdateAsync(model,ct))return NotFound();TempData["Success"]="Comment updated.";return RedirectToAction(nameof(History),new{model.ClassId,model.StudentId});}[HttpPost("Delete")][ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id,int classId,int studentId,CancellationToken ct){if(!await service.DeleteAsync(id,ct))return NotFound();TempData["Success"]="Comment deleted.";return RedirectToAction(nameof(History),new{classId,studentId});}[HttpGet("History")]public async Task<IActionResult> History(int classId,int studentId,CancellationToken ct){var m=await service.GetHistoryAsync(classId,studentId,ct);return m is null?NotFound():View(m);}}
